1	import {
2	  type jwtCustomizerConfigGuard,
3	  LogtoConfigs,
4	  LogtoTenantConfigKey,
5	  type AdminConsoleData,
6	  type IdTokenConfig,
7	  type LogtoConfig,
8	  type LogtoConfigKey,
9	  LogtoOidcConfigKey,
10	  type LogtoJwtTokenKey,
11	  type OidcPrivateKey,
12	  oidcPrivateKeyGuard,
13	  idTokenConfigGuard,
14	  type LogtoOidcConfigType,
15	} from '@logto/schemas';
16	import type { CommonQueryMethods } from '@silverhand/slonik';
17	import { sql } from '@silverhand/slonik';
18	import { type z } from 'zod';
19	
20	import { type WellKnownCache } from '#src/caches/well-known.js';
21	import { DeletionError } from '#src/errors/SlonikError/index.js';
22	import { convertToIdentifiers } from '#src/utils/sql.js';
23	
24	const { table, fields } = convertToIdentifiers(LogtoConfigs);
25	
26	export const createLogtoConfigQueries = (
27	  pool: CommonQueryMethods,
28	  wellKnownCache: WellKnownCache
29	) => {
30	  const upsertPrivateSigningKeys = async (privateKeys: OidcPrivateKey[]) =>
31	    pool.one<{ key: LogtoOidcConfigKey.PrivateKeys; value: unknown }>(sql`
32	      insert into ${table} (${fields.key}, ${fields.value})
33	        values (${LogtoOidcConfigKey.PrivateKeys}, ${sql.jsonb(privateKeys)})
34	        on conflict (${fields.tenantId}, ${fields.key}) do update set ${fields.value} = ${sql.jsonb(
35	          privateKeys
36	        )}
37	        returning ${fields.key}, ${fields.value}
38	    `);
39	
40	  const getAdminConsoleConfig = async () =>
41	    pool.one<{ value: unknown }>(sql`
42	      select ${fields.value} from ${table}
43	      where ${fields.key} = ${LogtoTenantConfigKey.AdminConsole}
44	    `);
45	
46	  const updateAdminConsoleConfig = async (value: Partial<AdminConsoleData>) =>
47	    pool.one<{ value: unknown }>(sql`
48	      update ${table}
49	      set ${fields.value} = coalesce(${fields.value},'{}'::jsonb) || ${sql.jsonb(value)}
50	      where ${fields.key} = ${LogtoTenantConfigKey.AdminConsole}
51	      returning ${fields.value}
52	    `);
53	
54	  const getCloudConnectionData = async () =>
55	    pool.one<{ value: unknown }>(sql`
56	      select ${fields.value} from ${table}
57	      where ${fields.key} = ${LogtoTenantConfigKey.CloudConnection}
58	    `);
59	
60	  const getRowsByKeys = async (keys: LogtoConfigKey[]) =>
61	    pool.query<LogtoConfig>(sql`
62	      select ${sql.join([fields.key, fields.value], sql`,`)} from ${table}
63	        where ${fields.key} in (${sql.join(keys, sql`,`)})
64	    `);
65	
66	  const deleteRowByKey = async (key: LogtoConfigKey) => {
67	    const { rowCount } = await pool.query(sql`
68	      delete from ${table}
69	      where ${fields.key}=${key}
70	    `);
71	
72	    if (rowCount < 1) {
73	      throw new DeletionError(LogtoConfigs.table, key);
74	    }
75	  };
76	
77	  const lockPrivateSigningKeys = async () =>
78	    pool.query(sql`
79	      select ${fields.key}
80	      from ${table}
81	      where ${fields.key} = ${LogtoOidcConfigKey.PrivateKeys}
82	      for update
83	    `);
84	
85	  const getPrivateSigningKeys = async (): Promise<OidcPrivateKey[]> => {
86	    const { rows } = await pool.query<LogtoConfig>(sql`
87	      select ${sql.join([fields.key, fields.value], sql`,`)} from ${table}
88	      where ${fields.key} = ${LogtoOidcConfigKey.PrivateKeys}
89	    `);
90	
91	    return oidcPrivateKeyGuard.array().parse(rows[0]?.value);
92	  };
93	
94	  const updateOidcConfigsByKey = async <
95	    T extends Exclude<LogtoOidcConfigKey, LogtoOidcConfigKey.PrivateKeys>,
96	  >(
97	    key: T,
98	    value: LogtoOidcConfigType[T]
99	  ) =>
100	    pool.query(sql`
101	      insert into ${table} (${fields.key}, ${fields.value})
102	        values (${key}, ${sql.jsonb(value)})
103	        on conflict (${fields.tenantId}, ${fields.key}) do update set ${fields.value} = ${sql.jsonb(value)}
104	        returning *
105	    `);
106	
107	  // Can not narrow down the type of value if we utilize `buildInsertIntoWithPool` method.
108	  const upsertJwtCustomizer = async <T extends LogtoJwtTokenKey>(
109	    key: T,
110	    value: z.infer<(typeof jwtCustomizerConfigGuard)[T]>
111	  ) =>
112	    pool.one<{ key: T; value: Record<string, string> }>(
113	      sql`
114	        insert into ${table} (${fields.key}, ${fields.value})
115	          values (${key}, ${sql.jsonb(value)})
116	          on conflict (${fields.tenantId}, ${fields.key}) do update set ${
117	            fields.value
118	          } = ${sql.jsonb(value)}
119	          returning *
120	      `
121	    );
122	
123	  const deleteJwtCustomizer = async <T extends LogtoJwtTokenKey>(key: T) => deleteRowByKey(key);
124	
125	  const getIdTokenConfig = wellKnownCache.memoize(async () => {
126	    const { rows } = await getRowsByKeys([LogtoTenantConfigKey.IdToken]);
127	
128	    if (rows.length === 0) {
129	      return null;
130	    }
131	
132	    return idTokenConfigGuard.parse(rows[0]?.value);
133	  }, ['id-token-config']);
134	
135	  const upsertIdTokenConfig = wellKnownCache.mutate(
136	    async (value: IdTokenConfig) =>
137	      pool.one<{ value: unknown }>(sql`
138	        insert into ${table} (${fields.key}, ${fields.value})
139	          values (${LogtoTenantConfigKey.IdToken}, ${sql.jsonb(value)})
140	          on conflict (${fields.tenantId}, ${fields.key}) do update set ${fields.value} = ${sql.jsonb(value)}
141	          returning ${fields.value}
142	      `),
143	    ['id-token-config']
144	  );
145	
146	  return {
147	    getAdminConsoleConfig,
148	    updateAdminConsoleConfig,
149	    getCloudConnectionData,
150	    getRowsByKeys,
151	    lockPrivateSigningKeys,
152	    getPrivateSigningKeys,
153	    upsertPrivateSigningKeys,
154	    updateOidcConfigsByKey,
155	    upsertJwtCustomizer,
156	    deleteJwtCustomizer,
157	    getIdTokenConfig,
158	    upsertIdTokenConfig,
159	  };
160	};
