1	import { adminTenantId, experience } from '@logto/schemas';
2	import { ConsoleLog } from '@logto/shared';
3	import type { MiddlewareType } from 'koa';
4	import Koa from 'koa';
5	import compose from 'koa-compose';
6	import koaCompress from 'koa-compress';
7	import mount from 'koa-mount';
8	import type { Provider } from 'oidc-provider';
9	
10	import { type CacheStore } from '#src/caches/types.js';
11	import { WellKnownCache } from '#src/caches/well-known.js';
12	import { AdminApps, EnvSet, UserApps } from '#src/env-set/index.js';
13	import { createCloudConnectionLibrary } from '#src/libraries/cloud-connection.js';
14	import { createConnectorLibrary } from '#src/libraries/connector.js';
