26	import koaSpaProxy from '#src/middleware/koa-spa-proxy.js';
27	import koaSpaSessionGuard from '#src/middleware/koa-spa-session-guard.js';
28	import initOidc from '#src/oidc/init.js';
29	import { mountCallbackRouter } from '#src/routes/callback.js';
30	import initApis, { initPublicWellKnownApis } from '#src/routes/init.js';
31	import initMeApis from '#src/routes-me/init.js';
32	import BasicSentinel from '#src/sentinel/basic-sentinel.js';
33	
34	import { redisCache } from '../caches/index.js';
35	import { SubscriptionLibrary } from '../libraries/subscription.js';
36	import koaConsentGuard from '../middleware/koa-consent-guard.js';
37	
38	import Libraries from './Libraries.js';
39	import Queries from './Queries.js';
40	import type TenantContext from './TenantContext.js';
41	import { getTenantDatabaseDsn } from './utils.js';
42	
43	const consoleLog = new ConsoleLog('tenant');
44	
45	/** Data for creating a tenant instance. */
46	type CreateTenant = {
47	  /** The unique identifier of the tenant. */
48	  id: string;
49	  /** The cache store for the tenant. */
50	  redisCache: CacheStore;
51	  /** The custom domain of the tenant, if applicable. */
52	  customDomain?: string;
53	};
54	
55	export default class Tenant implements TenantContext {
56	  static async create({ id, redisCache, customDomain }: CreateTenant): Promise<Tenant> {
57	    // Try to avoid unexpected "triggerUncaughtException" by using try-catch block
58	    try {
59	      // Treat the default database URL as the management URL
60	      const tenantDatabaseDsn = await getTenantDatabaseDsn(id);
61	      const envSet = new EnvSet(id, tenantDatabaseDsn);
62	      // Custom endpoint is used for building OIDC issuer URL when the request is a custom domain
63	      await envSet.load(customDomain);
64	
65	      return new Tenant(envSet, id, new WellKnownCache(id, redisCache));
66	    } catch (error) {
67	      consoleLog.error('Failed to create tenant:', id, error);
68	      throw error;
69	    }
70	  }
71	
72	  public readonly provider: Provider;
73	  public readonly run: MiddlewareType;
74	
75	  private readonly app: Koa;
76	
77	  readonly #createdAt = Date.now();
78	  #requestCount = 0;
79	  #onRequestEmpty?: () => Promise<void>;
80	
81	  // eslint-disable-next-line max-params
82	  private constructor(
83	    public readonly envSet: EnvSet,
84	    public readonly id: string,
85	    public readonly wellKnownCache: WellKnownCache,
86	    public readonly queries = new Queries(envSet.pool, wellKnownCache),
87	    public readonly logtoConfigs = createLogtoConfigLibrary(queries),
88	    public readonly cloudConnection = createCloudConnectionLibrary(logtoConfigs),
89	    public readonly connectors = createConnectorLibrary(queries, cloudConnection),
90	    public readonly subscription = new SubscriptionLibrary(
91	      id,
92	      queries,
93	      cloudConnection,
94	      redisCache
95	    ),
96	    public readonly libraries = new Libraries(
97	      id,
98	      queries,
99	      connectors,
100	      cloudConnection,
101	      logtoConfigs,
102	      subscription
103	    ),
104	    public readonly sentinel = new BasicSentinel(envSet.pool, queries)
105	  ) {
106	    const isAdminTenant = id === adminTenantId;
107	    const mountedApps = [
108	      ...Object.values(UserApps),
109	      ...(isAdminTenant ? Object.values(AdminApps) : []),
110	    ];
111	
112	    this.envSet = envSet;
113	
114	    // Init app
115	    const app = new Koa();
116	
117	    app.use(koaI18next());
118	    app.use(koaErrorHandler());
119	    app.use(koaOidcErrorHandler());
120	    app.use(koaSlonikErrorHandler());
121	    app.use(koaConnectorErrorHandler());
122	    app.use(koaCompress());
123	    app.use(koaSecurityHeaders(mountedApps, id));
124	
125	    // Mount OIDC
126	    const provider = initOidc(id, envSet, queries, libraries, logtoConfigs, subscription);
127	
128	    app.use(koaDeviceFlowShortcut());
129	    app.use(mount('/oidc', provider.app));
130	
131	    const tenantContext: TenantContext = {
132	      id,
133	      provider,
134	      queries,
135	      logtoConfigs,
136	      cloudConnection,
137	      connectors,
138	      libraries,
139	      envSet,
140	      sentinel,
141	      invalidateCache: this.invalidateCache.bind(this),
142	    };
143	
144	    // Sign-in experience callback via form submission
145	    mountCallbackRouter(app);
146	
147	    // Mount global well-known APIs
148	    app.use(mount('/.well-known', initPublicWellKnownApis(tenantContext)));
149	
150	    // Mount APIs
151	    app.use(mount('/api', initApis(tenantContext)));
152	
153	    const { isMultiTenancy } = EnvSet.values;
154	
155	    // Mount admin tenant APIs and app
156	    if (id === adminTenantId) {
157	      // Mount `/me` APIs for admin tenant
158	      app.use(mount('/me', initMeApis(tenantContext)));
159	
160	      // Mount Admin Console when needed
161	      // Skip in multi-tenancy mode since Logto Cloud serves Admin Console in this case
162	      if (!isMultiTenancy) {
163	        app.use(koaConsoleRedirectProxy(queries));
164	        app.use(
165	          mount(
166	            '/' + AdminApps.Console,
167	            koaSpaProxy({
168	              mountedApps,
169	              queries,
