 */", "newString": "/**
 * Promote a staged `Next` signing key to `Current` and demote the existing `Current` key to `Previous`.
 *
 * When a `Next` key is present, returns a new two-element array with the promoted key as `Current` and the
 * previously-current key as `Previous`; the old `Previous` key (if any) is dropped. When no `Next` key exists and
 * every key already carries an explicit status, the original array reference is returned unchanged. When no `Next`
 * key exists but some keys lack an explicit status, the normalized key array is returned.
 */
export const rotateOidcPrivateKeyStatuses = (
  privateKeys: LogtoOidcConfigType['oidc.privateKeys']
): OidcPrivateKey[] => {
  const hasNextKey = privateKeys.some(({ status }) => status === OidcSigningKeyStatus.Next);

  if (!hasNextKey) {
    // Nothing to promote. Avoid creating a new array when the input is already fully normalized.
    if (privateKeys.every(({ status }) => status !== undefined)) {
      return privateKeys;
    }

    return normalizeOidcPrivateKeys(privateKeys);
  }

  const normalizedPrivateKeys = normalizeOidcPrivateKeys(privateKeys);
  const nextKey = normalizedPrivateKeys.find(
    ({ status }) => status === OidcSigningKeyStatus.Next
  );
  const currentKey = normalizedPrivateKeys.find(
    ({ status }) => status === OidcSigningKeyStatus.Current
  );

  if (!nextKey || !currentKey) {
    throw new Error(
      'Malformed OIDC private key status configuration: expected exactly one Current key and one Next key.'
    );
  }

  return [
    { ...nextKey, status: OidcSigningKeyStatus.Current },
    { ...currentKey, status: OidcSigningKeyStatus.Previous },
  ];
};

